// Env hygiene for tests that SPAWN a hook entrypoint — mt#3528.
//
// A hook's stdout is a payload channel, not a log channel: ADR-028 §Output
// aggregation fixes the contract as "a hook's `stdout` must be exactly one JSON
// object." Any test that spawns a dispatcher and then parses its stdout is
// asserting that contract, so it has to hand the child an env a REAL hook would
// see.
//
// It previously did not. `tests/setup.ts` sets `MINSKY_LOG_MODE = "STRUCTURED"`
// for the in-process harness, and a spawn of the form
// `env: { ...process.env, … }` carries that into the child. In STRUCTURED mode
// the logger attaches a winston Console transport that writes structured JSON to
// stdout (`packages/shared/src/logger.ts` — "Agent logger: structured JSON to
// stdout"), so every transitively imported module's `log.info` lands in the
// payload. The mt#2975 console-silencing cannot help: its own doc comment records
// that it is gated on a globalThis flag which "does NOT cross the process
// boundary: a spawned child never runs the preload."
//
// Observed on the mt#2835 e2e canary before this fix — a real `log.info` from
// `packages/domain/src/ai/embedding-service-factory.ts` prepended to the payload:
//
//   {"level":"info","message":"Embedding fallback chain: openai → gemini",…}
//   {"hookSpecificOutput":{…}}
//
// That failure is CONFIG-dependent (it needs a configured embeddings
// `fallbackProvider`), so it reddened local developer runs while CI — which has
// no such credentials — stayed green. The worst split: the people positioned to
// act on the signal were the ones being trained to ignore it.
//
// @see docs/architecture/adr-028-guard-hook-dispatcher-consolidation.md — the stdout contract
// @see mt#3528 — this fix

/**
 * Env vars that attach the logger's Console transport to **stdout**, which a
 * spawned hook child must never inherit from a test runner.
 *
 * Both are read by `getLoggerConfig()` in `packages/shared/src/logger.ts`:
 * STRUCTURED mode adds the stdout transport outright, and `ENABLE_AGENT_LOGS`
 * adds it even in HUMAN mode.
 */
export const HARNESS_ONLY_LOG_ENV = ["MINSKY_LOG_MODE", "ENABLE_AGENT_LOGS"] as const;

/**
 * The env a spawned hook child should see: the inherited environment plus the
 * caller's overrides, MINUS the logging vars that exist only because a test
 * runner set them.
 *
 * **Deny-list, not allow-list — deliberate (PR #2529 R1).** The reviewer suggested
 * building from a minimal allow-list for stronger isolation. Declined: these tests
 * exist to run the REAL guard chain, and the guards read a wide, drifting set of
 * vars (`MINSKY_*` overrides, provider credentials, git/GitHub config, `HOME`,
 * `PATH`). An allow-list would have to enumerate all of them, would go stale
 * silently as guards are added, and — worst — would change WHAT the canary
 * exercises, weakening the very realism that makes it a canary. The failure mode
 * being guarded is narrow and known: env that redirects logging onto stdout. A
 * targeted deny-list matches that shape, and the accompanying regression test
 * pins it so a future `env: { ...process.env }` fails loudly instead of silently.
 */
export function hookChildEnv(
  overrides: Record<string, string> = {}
): Record<string, string | undefined> {
  const env: Record<string, string | undefined> = { ...process.env, ...overrides };
  for (const key of HARNESS_ONLY_LOG_ENV) delete env[key];
  return env;
}
